#[derive(Debug, Clone)]
enum Exp {
    Const(i32),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Plus(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), r) => r, // 0 + r = r
                (l, Exp::Const(0)) => l, // l + 0 = l
                (Exp::Const(l_val), Exp::Const(r_val)) => {
                    Exp::Const(l_val + r_val) // l + r = l + r (constant folding)
                }
                (l, r) => Exp::Plus(Box::new(l), Box::new(r)), // return unchanged
            }
        }
        Exp::Mult(left, right) => {
            let left_optimized = optimize(*left);
            let right_optimized = optimize(*right);
            match (left_optimized, right_optimized) {
                (Exp::Const(0), _) => Exp::Const(0), // 0 * r = 0
                (_, Exp::Const(0)) => Exp::Const(0), // l * 0 = 0
                (Exp::Const(1), r) => r, // 1 * r = r
                (l, Exp::Const(1)) => l, // l * 1 = l
                (Exp::Const(l_val), Exp::Const(r_val)) => {
                    Exp::Const(l_val * r_val) // l * r = l * r (constant folding)
                }
                (l, r) => Exp::Mult(Box::new(l), Box::new(r)), // return unchanged
            }
        }
        other => other, // Const and Var are unchanged
    }
}

